const title=$('Config').first().json.saleSheetName;
const sheets=$input.first().json.sheets||[];
const found=sheets.find(s=>String((s.properties||{}).title||'')===title);
return [{json:{needsCreate:!found,sheetId:found ? found.properties.sheetId : null}}];

const values=$input.first().json.values||[];
if(values.length<2) return [];
const headers=values[0].map(v=>String(v??'').trim());
const max=Math.max(1,Math.min(50,Number($('Config').first().json.maxAuditItems||20)));
function obj(row){const o={};headers.forEach((h,i)=>o[h]=row[i]??'');return o;}
function t(v){return v===null||v===undefined?'':String(v).trim();}
function n(v){const x=Number(v);return Number.isFinite(x)?x:null;}
const out=[];
for(let i=1;i<values.length;i++){
  const r=obj(values[i]);
  const itemId=t(r['Item ID']);
  const qty=n(r['Available Qty']);
  const price=n(r.Price);
  if(!itemId || qty===null || qty<=0 || price===null || price<=0) continue;
  out.push({json:{
    itemId,
    sku:t(r.SKU),
    title:t(r.Title),
    ebayUrl:t(r['eBay URL'])||('https://www.ebay.com/itm/'+itemId),
    currentPrice:price
  }});
  if(out.length>=max) break;
}
return out;

const cfg=$('Config').first().json;
const selected=$('Select Active Listings').all();
const responses=$input.all();
const HEADERS=['Item ID','SKU','Title','Our Price','Exact Market Median','Suggested Sale','Net Profit','Margin %','Min Price','Decision','Note'];
const oldValues=($('Read Existing Sale Agent').first().json.values||[]);
const oldHeaders=(oldValues[0]||[]).map(v=>String(v??'').trim());
function oldObj(row){const o={};oldHeaders.forEach((h,i)=>o[h]=row[i]??'');return o;}
function t(v){return v===null||v===undefined?'':String(v).trim();}
function num(v){if(v===null||v===undefined||v==='')return null;const x=Number(v);return Number.isFinite(x)?x:null;}
function money(v){return Math.round((Number(v||0)+Number.EPSILON)*100)/100;}
function ceilMoney(v){return Math.ceil(v*100-1e-9)/100;}
function parseItemId(titleCell){const m=String(titleCell||'').match(/\/itm\/(\d+)/);return m?m[1]:'';}
function parseSale(text){const m=String(text||'').match(/\$([0-9]+(?:\.[0-9]+)?)/);return m?Number(m[1]):null;}

// Economics: eBay fees apply to item + shipping charged to buyer
const feeRate=Number(cfg.ebayFeeRate??0.1325);
const perOrder=Number(cfg.ebayPerOrderFee??0.40);
const cost=Number(cfg.productCost??3);
const label=Number(cfg.shippingLabelCost??0);
const minMargin=Number(cfg.minMarginPct??25)/100;
const minNet=Number(cfg.minNetProfit??1);
function econ(sale,ship){const gross=sale+ship;const net=gross-gross*feeRate-perOrder-cost-label;return {net:money(net),margin:gross>0?net/gross:0};}
function floorPrice(ship){
  const fixed=perOrder+cost+label;
  const byMargin=(1-feeRate-minMargin)>0?fixed/(1-feeRate-minMargin)-ship:Infinity;
  const byProfit=(minNet+fixed)/(1-feeRate)-ship;
  return ceilMoney(Math.max(0.99,byMargin,byProfit));
}

// Previous decisions keyed by Item ID only (survive price/median changes)
const oldMap={};
for(let i=1;i<oldValues.length;i++){
  const r=oldObj(oldValues[i]);
  const itemId=t(r['Item ID'])||parseItemId(r.Title);
  if(!itemId) continue;
  oldMap[itemId]={decision:t(r.Decision).toUpperCase(),suggestion:t(r['Suggested Sale']),obj:r};
}

const rows=[];
const seen=new Set();
const generatedAt=new Date().toISOString();
let audited=0,insufficient=0,notAboveMarket=0,marginBlocked=0,recheck=0,stale=0;
for(let i=0;i<selected.length;i++){
  const src=selected[i].json;
  const body=(responses[i]&&responses[i].json)||{};
  if(!body.ok || !body.audit){insufficient++;continue;}
  audited++;
  const audit=body.audit;
  const data=audit.data||audit.DATA||{};
  const market=audit.market||audit.MARKET||{};
  const exact=Number(market.exactCompetitorCount||0);
  const median=num(market.medianComparableBuyerTotal);
  const ownTotal=num(market.ourBuyerTotal);
  let shipping=num(data.shipping);
  if(shipping===null && ownTotal!==null) shipping=money(Math.max(0,ownTotal-src.currentPrice));
  shipping=shipping||0;
  if(exact<2 || median===null || median<=0){insufficient++;continue;}
  const targetItem=money(Math.max(0.99,median-shipping));
  if(src.currentPrice<=targetItem*1.03){notAboveMarket++;continue;}
  const needed=((src.currentPrice-targetItem)/src.currentPrice)*100;
  let discount=Math.max(5,Math.min(15,Math.round(needed/5)*5));
  const floor=floorPrice(shipping);
  const notes=[];
  while(discount>=5 && money(src.currentPrice*(1-discount/100))<floor){discount-=5;notes.push('Discount capped by margin');}
  if(discount<5){marginBlocked++;continue;}
  const salePrice=money(src.currentPrice*(1-discount/100));
  const e=econ(salePrice,shipping);
  const suggestion=discount+'% → $'+salePrice.toFixed(2);
  const old=oldMap[src.itemId];
  let decision=old&&['APPROVE','RECHECK','SKIP','DONE','FAILED'].includes(old.decision)?old.decision:'';
  if(decision==='RECHECK') decision='';
  if(decision==='APPROVE' && old.suggestion && old.suggestion!==suggestion){
    const approved=parseSale(old.suggestion);
    if(approved===null || salePrice<approved){
      decision='RECHECK';recheck++;
      notes.push('Deeper than approved ('+old.suggestion+') — type APPROVE again to confirm');
    }else{
      notes.push('Repriced up since approval (was '+old.suggestion+')');
    }
  }
  const safeTitle=(src.title||src.sku||src.itemId).replace(/"/g,'""');
  const safeUrl=String(src.ebayUrl||('https://www.ebay.com/itm/'+src.itemId)).replace(/"/g,'');
  seen.add(src.itemId);
  rows.push([
    src.itemId,
    src.sku,
    '=HYPERLINK("'+safeUrl+'","'+safeTitle+'")',
    src.currentPrice,
    median,
    suggestion,
    e.net,
    Math.round(e.margin*1000)/10,
    floor,
    decision,
    [...new Set(notes)].join('; ')
  ]);
}

// Carry over decided rows that were not re-suggested, so nothing disappears silently
for(const itemId of Object.keys(oldMap)){
  if(seen.has(itemId)) continue;
  const old=oldMap[itemId];
  let decision=old.decision,note=t(old.obj.Note);
  if(decision==='APPROVE'||decision==='RECHECK'){
    decision='STALE';stale++;
    note='Not suggested this run (price changed, no longer above market, margin, or audit failed). Clear row or wait for a new suggestion.';
  }else if(decision!=='DONE' && decision!=='FAILED') continue;
  const row=HEADERS.map(h=>h==='Item ID'?itemId:(old.obj[h]??''));
  row[HEADERS.indexOf('Decision')]=decision;
  row[HEADERS.indexOf('Note')]=note;
  rows.push(row);
}
return [{json:{rows,rowCount:rows.length,audited,insufficient,notAboveMarket,marginBlocked,recheck,stale,generatedAt}}];

const rows=$('Build Simple Sale Rows').first().json.rows||[];
const generatedAt=$('Build Simple Sale Rows').first().json.generatedAt;
function salePrice(text){
  const m=String(text||'').match(/\$([0-9]+(?:\.[0-9]+)?)/);
  return m?Number(m[1]):null;
}
const out=[];
for(let i=0;i<rows.length;i++){
  const r=rows[i];
  if(String(r[9]||'').trim().toUpperCase()!=='APPROVE') continue;
  const itemId=String(r[0]||'').trim();
  const proposed=salePrice(r[5]);
  const floor=Number(r[8]);
  if(!itemId || proposed===null || !Number.isFinite(floor) || proposed<floor) continue;
  out.push({json:{
    kind:'approval',
    rowNumber:i+2,
    itemId,
    sku:String(r[1]||''),
    currentPrice:Number(r[3]),
    proposedPrice:proposed,
    priceFloor:floor,
    analyzedAt:generatedAt
  }});
}
return out.length?out:[{json:{kind:'none'}}];

const selected=$('Select APPROVE Rows').all().filter(x=>x.json.kind==='approval');
const responses=$input.all();
const data=[];
let done=0,failed=0;
for(let i=0;i<selected.length;i++){
  const src=selected[i].json;
  const body=(responses[i]&&responses[i].json)||{};
  const ok=body.ok===true;
  if(ok) done++; else failed++;
  data.push({
    range:"'"+$('Config').first().json.saleSheetName+"'!J"+src.rowNumber,
    majorDimension:'ROWS',
    values:[[ok?'DONE':'FAILED']]
  });
}
return [{json:{data,done,failed,attempted:selected.length}}];

const s=$('Build Simple Sale Rows').first().json;
let attempted=0,done=0,failed=0;
try{
  const e=$('Build Execution Status').first().json;
  attempted=Number(e.attempted||0); done=Number(e.done||0); failed=Number(e.failed||0);
}catch(err){}
return [{json:{
  ok:true,
  suggestions:s.rowCount,
  audited:s.audited,
  insufficient:s.insufficient,
  notAboveMarket:s.notAboveMarket,
  marginBlocked:s.marginBlocked,
  needsRecheck:s.recheck,
  staleApprovals:s.stale,
  approvalsAttempted:attempted,
  salesCreated:done,
  salesFailed:failed
}}];
